import csv
import io
import re
from typing import List, Dict, Any

_DATE_RE = re.compile(
    r"^(?:\d{1,4}[-/]\d{1,2}[-/]\d{1,4}|\d{1,2}[.-]\d{1,2}[.-]\d{1,4})$"
)
_TIME_RE = re.compile(r"^\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?$")
_HEADER_WORDS = {
    "date", "time", "datetime", "timestamp", "id", "key", "code",
    "qty", "quantity", "count", "amount", "price", "cost", "value",
    "type", "category", "class", "name", "title", "description",
    "comment", "comments", "note", "notes", "url", "uri", "link",
    "address", "email", "phone", "status", "product", "item",
    "number", "no", "index", "field", "column"
}


def _is_data_record(row: List[str]) -> bool:
    if not row:
        return False
    first = row[0].strip()
    if not _DATE_RE.match(first):
        return False
    if len(row) > 1 and row[1].strip() and _TIME_RE.match(row[1].strip()):
        return True
    return True


def _header_score(row: List[str], expected_width: int) -> int:
    if not row:
        return -100
    score = 0
    if len(row) == expected_width:
        score += 5
    elif len(row) >= 2:
        score += 1
    if _is_data_record(row):
        score -= 20

    textual = 0
    recognized = 0
    for value in row:
        text = value.strip().lower()
        if not text:
            continue
        if re.search(r"[A-Za-z]", text):
            textual += 1
        words = set(re.findall(r"[a-z]+", text))
        if words & _HEADER_WORDS:
            recognized += 1

    score += min(textual, 5)
    score += recognized * 3
    if textual >= max(2, min(len(row), 4)):
        score += 2
    return score


def _fit_width(row: List[str], width: int) -> List[str]:
    if len(row) == width:
        return list(row)
    if len(row) < width:
        return list(row) + [""] * (width - len(row))
    head = list(row[:width - 1])
    head.append(",".join(row[width - 1:]))
    return head


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raise TypeError("raw_csv must be a string")

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
        skipinitialspace=False
    )

    records = []
    try:
        for row in reader:
            if row is not None:
                records.append(row)
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            try:
                records.append(next(csv.reader(
                    [line],
                    delimiter=",",
                    quotechar='"',
                    doublequote=True,
                    strict=False
                )))
            except (csv.Error, StopIteration):
                records.append(line.split(","))

    nonempty = [(index, row) for index, row in enumerate(records)
                if any(cell != "" for cell in row)]

    if not nonempty:
        return {"columns": [], "rows": []}

    expected_width = 9
    first_data_position = None
    for position, (_, row) in enumerate(nonempty):
        if _is_data_record(row):
            first_data_position = position
            break

    search_end = first_data_position if first_data_position is not None else len(nonempty)
    candidates = nonempty[:search_end]

    if candidates:
        best_index, best_row = max(
            candidates,
            key=lambda item: (_header_score(item[1], expected_width), -item[0])
        )
        if _header_score(best_row, expected_width) < 2:
            best_index, best_row = candidates[0]
    else:
        best_index, best_row = nonempty[0]

    header_record_index = best_index
    columns = _fit_width(best_row, expected_width)

    rows = []
    for index, row in enumerate(records):
        if index <= header_record_index:
            continue
        if not row or not any(cell != "" for cell in row):
            continue
        rows.append(_fit_width(row, expected_width))

    return {"columns": columns, "rows": rows}
